def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # The last move is a strict one-shot improvement for any known history.
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    # Short capped runs of recent actions.
    my_D_run = 0
    if my_last == 'D':
        my_D_run = 1
        if n >= 2 and history[-2][0] == 'D':
            my_D_run = 2
            if n >= 3 and history[-3][0] == 'D':
                my_D_run = 3

    opp_D_run = 0
    if opp_last == 'D':
        opp_D_run = 1
        if n >= 2 and history[-2][1] == 'D':
            opp_D_run = 2
            if n >= 3 and history[-3][1] == 'D':
                opp_D_run = 3

    # Aggregate statistics for the current match.
    opp_d = 0
    my_d = 0
    r5_c = 0
    r10_c = 0
    r15_c = 0
    forgive = 0
    punish = 0

    start5 = n - 5
    start10 = n - 10
    start15 = n - 15

    prev_a = prev_b = pprev_b = ''
    for i in range(n):
        a = history[i][0]
        b = history[i][1]

        if b == 'C':
            if i >= start5:
                r5_c += 1
            if i >= start10:
                r10_c += 1
            if i >= start15:
                r15_c += 1
        else:
            opp_d += 1

        if a == 'D':
            my_d += 1

        # Count only unprovoked exploits: our D against an opponent who
        # cooperated in the same round and was already cooperating before it.
        if i > 0 and prev_a == 'D' and prev_b == 'C' and pprev_b == 'C':
            if b == 'C':
                forgive += 1
            elif b == 'D':
                punish += 1

        pprev_b = prev_b
        prev_a = a
        prev_b = b

    recent5 = r5_c / (n if n < 5 else 5)
    recent10 = r10_c / (n if n < 10 else 10)
    recent15 = r15_c / (n if n < 15 else 15)
    opp_coop_rate = (n - opp_d) / n

    # Against a mostly defective opponent, keep defecting.
    if opp_coop_rate <= 0.25 and recent15 <= 0.35:
        return 'D'

    # Known forgiving opponent: exploit in bounded bursts.
    if (punish == 0 and forgive > 0) or (forgive >= 3 and punish * 2 <= forgive and recent15 >= 0.9):
        if opp_last == 'C':
            if my_last == 'C':
                return 'D'
            if my_D_run < 3 and recent10 >= 0.70:
                return 'D'
            return 'C'

        # Opponent defected. If this looks like punishment or a short
        # uncooperative blip, try to restore cooperation; otherwise exploit.
        if opp_D_run >= 2 or recent10 < 0.50:
            return 'D'
        if my_last == 'C' and n >= 2 and history[-2][0] == 'D':
            return 'C'
        return 'D'

    # Known punishing opponent: be forgiving and contrite.
    if punish > 0:
        # A cautious second probe is allowed only if the opponent has clearly
        # forgiven many earlier exploitations and has been cooperative for a
        # long recent stretch.
        if opp_last == 'C' and my_last == 'C':
            if forgive >= 2 and punish * 3 <= forgive and recent15 >= 0.95:
                if rng.random() < 0.03:
                    return 'D'
            return 'C'

        if opp_last == 'D':
            # If a short defection streak began right after mutual cooperation,
            # treat it as unprovoked; otherwise assume it is punishment.
            if recent10 >= 0.70 and opp_D_run <= 2:
                start = n - opp_D_run - 1
                if start >= 0 and history[start][0] == 'C' and history[start][1] == 'C':
                    return 'D'
                return 'C'
            return 'D'

        return 'C'

    # Unknown / mixed state: contrite TFT-style default, plus one controlled
    # probe against apparently very cooperative opponents.
    if opp_last == 'D':
        if my_last == 'C':
            if n >= 2 and history[-2][0] == 'D' and recent10 >= 0.60:
                return 'C'
            return 'D'

        # my_last == 'D'
        if n >= 2 and history[-2][1] == 'C' and recent10 >= 0.60:
            return 'C'
        if opp_D_run == 1 and recent10 >= 0.70:
            return 'C'
        return 'D'

    # Opponent cooperated.
    if my_last == 'D':
        return 'C'

    # Mutual cooperation. Try a single test defection if the opponent has been
    # almost perfectly cooperative and we have not defected yet.
    if my_d == 0 and opp_coop_rate >= 0.90 and recent15 >= 0.90 and n >= 18:
        return 'D'

    # If we have defected only as punishment, there is no exploitation data.
    # Occasionally probe again in a very long cooperative stretch.
    if punish == 0 and forgive == 0 and opp_coop_rate >= 0.95 and recent15 >= 0.95 and recent5 >= 0.80 and n >= 40:
        if rng.random() < 0.05:
            return 'D'

    return 'C'
